import{_ as e,c as r,o as n,ag as s}from"./chunks/framework.CoPVQkzc.js";const h=JSON.parse('{"title":"Glossary","description":"Terminology reference","frontmatter":{"title":"Glossary","description":"Terminology reference"},"headers":[],"relativePath":"engine/glossary.md","filePath":"engine/glossary.md","lastUpdated":1788476353000}'),o={name:"engine/glossary.md"};function a(d,t,i,g,c,l){return n(),r("div",null,t[0]||(t[0]=[s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Key terms and concepts used in OIE.</p><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td><strong>ACK</strong></td><td>Acknowledgment message sent back to a sender confirming receipt of a message (common in HL7)</td></tr><tr><td><strong>Attachment</strong></td><td>Binary or large content extracted from a message and stored separately</td></tr><tr><td><strong>Batch</strong></td><td>A single inbound payload that is split into multiple discrete messages</td></tr><tr><td><strong>Channel</strong></td><td>The fundamental processing unit in OIE; defines a complete message pipeline from source to destination(s)</td></tr><tr><td><strong>Channel Group</strong></td><td>An organizational container for grouping related channels</td></tr><tr><td><strong>Channel Map</strong></td><td>A key-value store scoped to a single message across all connectors in a channel</td></tr><tr><td><strong>Channel Writer/Reader</strong></td><td>Internal connectors for routing messages between channels within the same OIE instance</td></tr><tr><td><strong>Code Template</strong></td><td>A reusable JavaScript function or code snippet shared across channels</td></tr><tr><td><strong>Configuration Map</strong></td><td>Server-wide key-value pairs accessible in all channel scripts; configured in Settings</td></tr><tr><td><strong>Connector</strong></td><td>A protocol-specific endpoint (source or destination) that handles message I/O</td></tr><tr><td><strong>Connector Map</strong></td><td>A key-value store scoped to a single message within a single connector</td></tr><tr><td><strong>Dashboard</strong></td><td>The main operational view showing deployed channels and their real-time statistics</td></tr><tr><td><strong>Data Pruner</strong></td><td>A background process that automatically removes old message data</td></tr><tr><td><strong>Data Type</strong></td><td>A message format parser/serializer (e.g., HL7 v2.x, XML, JSON, DICOM)</td></tr><tr><td><strong>Deploy</strong></td><td>Loading a channel into the engine so it can process messages</td></tr><tr><td><strong>Derby</strong></td><td>Apache Derby; the embedded database used by default for development</td></tr><tr><td><strong>Destination</strong></td><td>A connector that sends processed messages to an external system or another channel</td></tr><tr><td><strong>Destination Set</strong></td><td>The set of destinations that will process a given message; can be modified dynamically in scripts</td></tr><tr><td><strong>DICOM</strong></td><td>Digital Imaging and Communications in Medicine; a standard for medical imaging</td></tr><tr><td><strong>Donkey</strong></td><td>The internal message processing engine that handles queuing, storage, and message lifecycle</td></tr><tr><td><strong>E4X</strong></td><td>ECMAScript for XML; the XML syntax used in JavaScript transformers to access message fields</td></tr><tr><td><strong>EDI</strong></td><td>Electronic Data Interchange; a standard for business document exchange</td></tr><tr><td><strong>Extension</strong></td><td>A plugin that adds functionality to OIE (connectors, data types, plugins, etc.)</td></tr><tr><td><strong>Filter</strong></td><td>A set of rules that determine whether a message should be processed or rejected</td></tr><tr><td><strong>Global Channel Map</strong></td><td>A key-value store shared across all messages within a specific channel</td></tr><tr><td><strong>Global Map</strong></td><td>A key-value store shared across all channels on the server</td></tr><tr><td><strong>HL7</strong></td><td>Health Level Seven; a set of international standards for healthcare data exchange</td></tr><tr><td><strong>Iterator</strong></td><td>A transformer step type that loops over repeating segments or elements</td></tr><tr><td><strong>Mapper</strong></td><td>A transformer step type that extracts a value from the source message into a variable</td></tr><tr><td><strong>Message</strong></td><td>A discrete unit of data processed by a channel</td></tr><tr><td><strong>Message Browser</strong></td><td>The UI for searching, viewing, and managing individual messages</td></tr><tr><td><strong>Message Builder</strong></td><td>A transformer step type that sets a field in the outbound message</td></tr><tr><td><strong>Message Storage Mode</strong></td><td>Controls how much message content is persisted (Development, Production, Raw, Metadata, Disabled)</td></tr><tr><td><strong>MLLP</strong></td><td>Minimum Lower Layer Protocol; the standard framing protocol for HL7 over TCP</td></tr><tr><td><strong>NACK</strong></td><td>Negative Acknowledgment; indicates a message was received but could not be processed</td></tr><tr><td><strong>NCPDP</strong></td><td>National Council for Prescription Drug Programs; a pharmacy transaction standard</td></tr><tr><td><strong>OIE</strong></td><td>Open Integration Engine; this project</td></tr><tr><td><strong>Postprocessor</strong></td><td>A channel script that runs after all destinations have processed a message</td></tr><tr><td><strong>Preprocessor</strong></td><td>A channel script that runs before the source transformer, receiving the raw message</td></tr><tr><td><strong>Pruning</strong></td><td>The process of removing old message data from the database</td></tr><tr><td><strong>Queue</strong></td><td>A persistent buffer for messages waiting to be sent by a destination connector</td></tr><tr><td><strong>Response</strong></td><td>Data returned by a destination system after receiving a message</td></tr><tr><td><strong>Response Map</strong></td><td>A key-value store for destination responses, used to return responses to the source</td></tr><tr><td><strong>Rhino</strong></td><td>Mozilla Rhino; the JavaScript engine used by OIE</td></tr><tr><td><strong>Rule</strong></td><td>A single condition within a filter (Rule Builder, JavaScript, or External Script)</td></tr><tr><td><strong>Serialization</strong></td><td>Converting an internal message representation to an output format string</td></tr><tr><td><strong>Source</strong></td><td>The connector that receives inbound messages for a channel</td></tr><tr><td><strong>Source Map</strong></td><td>A key-value store populated by the source connector with metadata (e.g., remote address)</td></tr><tr><td><strong>Step</strong></td><td>A single operation within a transformer (Mapper, Message Builder, JavaScript, etc.)</td></tr><tr><td><strong>Tag</strong></td><td>A label applied to channels for organizational filtering</td></tr><tr><td><strong>Template</strong></td><td>The content pattern used by a destination connector, supporting variable substitution</td></tr><tr><td><strong>Transformer</strong></td><td>A chain of steps that modify message content as it passes through a connector</td></tr><tr><td><strong>Transmission Mode</strong></td><td>The framing protocol used by TCP connectors (MLLP, Basic)</td></tr><tr><td><strong>Undeploy</strong></td><td>Removing a channel from the engine so it stops processing messages</td></tr><tr><td><strong>VM</strong></td><td>The underlying connector protocol for channel-to-channel routing; exposed in the UI as Channel Reader (source) and Channel Writer (destination)</td></tr></tbody></table>',3)]))}const m=e(o,[["render",a]]);export{h as __pageData,m as default};
